122: .hire-prompt:hover { border-color: var(--acid); background: #2a3322; }
123: .hire-icon { width: 27px; height: 27px; flex: 0 0 27px; display: grid; place-items: center; color: #151a11; background: var(--acid); font: 700 20px/1 var(--display); }
