128: .hire-prompt strong { color: var(--acid); font: 700 15px/1 var(--display); white-space: nowrap; }
129: .hire-prompt strong i { color: #899280; font: normal 10px var(--body); }
130: .hire-prompt:disabled { filter: grayscale(.8); opacity: .65; }
131: .deck-footer { min-height: 17px; display: flex; justify-content: space-between; align-items: center; color: #737d75; font: 700 8px/1 var(--body); letter-spacing: .65px; }
